arguments.command:
python -c "
import py_compile, glob, os
errors = []
for f in glob.glob('harness/**/*.py', recursive=True):
    try:
        py_compile.compile(f, doraise=True)
    except py_compile.PyCompileError as e:
        errors.append(str(e))
if errors:
    for e in errors:
        print(e)
else:
    print('All harness Python files parse OK')
"
